import{z as n,x as A,o as e,c as d,q as t,j as s,D as E,d as l,s as r,S as i,b as o}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"L4 / L7 负载均衡","description":"","frontmatter":{"title":"L4 / L7 负载均衡","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/l4-l7-load-balancing.md","filePath":"cs/l4-l7-load-balancing.md","lastUpdated":1791063341000}'),p={name:"cs/l4-l7-load-balancing.md"};function L(C,a,c,h,D,m){const B=A("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="l4-l7-负载均衡" tabindex="-1">L4 / L7 负载均衡 <a class="header-anchor" href="#l4-l7-负载均衡" aria-label="Permalink to &quot;L4 / L7 负载均衡&quot;">​</a></h1><div class="epigraph"><p>L4 按五元组把连接钉到后端；L7 终止协议、看 Host/路径/Cookie 再选。能力与代价一层一层上去。</p><footer>—— 据 RFC 9110；负载均衡实践；Maglev 课将细化一致性哈希整理</footer></div><p><a href="/cs/ecmp-hashing">ECMP</a> 在路由器。<a href="/cs/edge-compute">上一课</a> 要把请求分到实例。缺口是 <strong>LB 分层</strong>：L4 vs L7、粘滞、健康检查。本课不把 Maglev 算法写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多后端提供同一服务。L4（NAT 或 DR）：不看 HTTP，快，SSL 可直达后端。L7：能按 URL 分流、重试幂等 GET、塞头，但要证书与缓冲，HOL/流控在 LB 上。WS 升级、gRPC、H3 都要求 L7 懂协议。健康检查失败应摘除，否则 GeoDNS 再准也打到死进程。</p><p>不要把 DNS 轮询当健康检查。</p><p><span class="marginnote">DSR/NAT 模式是实现。本课钉层。VIP 是前端地址。</span></p><p><span class="marginnote">术语翻译：粘滞（会话保持）就是「让同一用户的后续请求总回同一台后端」——因为登录态可能存在那台机器的内存里。L4 用五元组哈希天然粘住一条连接，L7 可以读 Cookie 按用户粘。</span></p><h3 id="层决定看见什么" tabindex="-1">层决定看见什么 <a class="header-anchor" href="#层决定看见什么" aria-label="Permalink to &quot;层决定看见什么&quot;">​</a></h3><p>L4 粘五元组；L7 看 Host 与路径。健康检查必要。H3/gRPC/WS 逼 L7 懂协议。DNS 轮询不是健康检查。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 L4/L7 能力表。画：VIP → 选择 → 后端。与 WFQ：LB 选服务器，WFQ 分带宽。</p>',12)),(e(),s(i,null,{default:E(()=>[r(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20VIP%5B%22%E8%99%9A%E6%8B%9F%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20L4%5B%22%E4%BA%94%E5%85%83%E7%BB%84%E7%B2%98%E6%BB%9E%22%5D%0A%20%20VIP%20--%3E%20L7%5B%22%E8%A7%A3%E6%9E%90%E5%BA%94%E7%94%A8%E5%A4%B4%22%5D%0A%20%20L4%20--%3E%20BE%5B%22%E5%90%8E%E7%AB%AF%22%5D%0A%20%20L7%20--%3E%20BE%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[l("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"连接迁移：L4 钉四元组，QUIC 迁移要 CID 感知（下一课 Maglev 相关）。PFC 与 LB 无关。SYN flood 打在 L4 VIP 上，cookies 可在 LB。度量：最少连接 vs 轮询，极化类似 ECMP 大象。",-1)),(e(),s(i,null,{default:E(()=>[r(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E6%96%B0%E8%AF%B7%E6%B1%82%E5%88%B0%20VIP%22%5D%20--%3E%20HC%7B%22%E7%9B%AE%E6%A0%87%E5%90%8E%E7%AB%AF%E5%81%A5%E5%BA%B7%E6%A3%80%E6%9F%A5%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20HC%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20PICK%5B%22%E6%8C%89%E7%AE%97%E6%B3%95%E9%80%89%E4%B8%80%E5%8F%B0%22%5D%0A%20%20HC%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%22%7C%20EJECT%5B%22%E6%91%98%E9%99%A4%2C%20%E6%B5%81%E9%87%8F%E6%94%B9%E6%8A%95%E5%81%A5%E5%BA%B7%E6%88%90%E5%91%98%22%5D%0A%20%20PICK%20--%3E%20STICK%7B%22%E7%B2%98%E6%BB%9E%E8%A7%84%E5%88%99%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20STICK%20--%3E%7C%22%E4%BA%94%E5%85%83%E7%BB%84%2FCookie%20%E5%91%BD%E4%B8%AD%22%7C%20SAME%5B%22%E5%9B%9E%E5%90%8C%E4%B8%80%E5%90%8E%E7%AB%AF%2C%20%E7%99%BB%E5%BD%95%E6%80%81%E4%B8%8D%E4%B8%A2%22%5D%0A%20%20STICK%20--%3E%7C%22%E6%96%B0%E4%BC%9A%E8%AF%9D%22%7C%20ANY%5B%22%E5%88%86%E7%BB%99%E8%B4%9F%E8%BD%BD%E6%9C%80%E8%BD%BB%E7%9A%84%E5%81%A5%E5%BA%B7%E5%90%8E%E7%AB%AF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">数字实例：常见健康检查配置是每 2–5 秒探测一次、连续 3 次失败才摘除——一个后端崩溃后，最坏十几秒流量才完全避开它。对照 DNS 轮询：TTL 动辄 300 秒，等它过期用户早刷新一百次了。</span></p><p><span class="marginnote">常见误区：初学者容易以为「域名配多个 A 记录轮询」就等于负载均衡加高可用。DNS 只负责把名字摊到几个 IP，从不探测谁活着；某台宕机后，缓存的解析仍把用户往死进程上送，直到 TTL 过期——所以健康检查必须放在 LB 层做。</span></p><p>安全：L7 可 WAF，扩大攻击面也扩大防护点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入服务网格 sidecar 的全部。Maglev 是下一课。后课默认：L4 保连接；L7 看内容；健康检查必要。</p><p>把有状态会话只放一台且无粘滞，用户会随机丢登录。</p><p>下一课<a href="/cs/maglev-lb">Maglev</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>L4 快、协议不可见；L7 智、要终止。</li><li>粘滞与健康检查决定正确性。</li><li>新运输（H3/gRPC）逼 L7 升级。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：HTTP 语义；LB 实践。</li></ul>',9))])}const f=n(p,[["render",L]]);export{P as __pageData,f as default};
